  IEnumerator R18Pose(Vector2 request){var p=WideLegal(request.x,request.y);Simulation.Player.X=p.x;Simulation.Player.Y=p.y;lastX=p.x;lastY=p.y;a2rPlay.visualPoseAssignments++;Simulation.Enemies.Clear();for(int i=0;i<12;i++){UpdateViews();yield return null;}}
  IEnumerator A2RR18Proof(){
   var report=new R18Report();yield return A2RNatureSize(1920);A2RSetLook(true);a2rModels.SetLook(true);
   var perf=new R14Perf();yield return A2RR14Counter(perf,"camp enemies retained / r18");a2rModels.SetLook(false);yield return A2RR14Counter(perf,"same camp enemies retained / r14 3D OFF mode");a2rModels.SetLook(true);File.WriteAllText(Path.Combine(a2rPlayOutput,"r18-performance.json"),JsonUtility.ToJson(perf,true));
   foreach(var item in a2rWeb.Result.items){if(!item.added)continue;var card=a2rWeb.VisualRoot.Find(item.id+" "+item.kind+" web XY");if(card==null||!card.gameObject.activeInHierarchy)continue;var row=report.cards.Find(x=>x.kind==item.kind);if(row==null){row=new R17Kind{kind=item.kind};report.cards.Add(row);}row.ids.Add(item.id);if(item.groundProjected){row.floor++;report.floor++;}else{row.standing++;report.standing++;if(item.kind=="forest_wall")report.forestWalls++;}}
   foreach(var item in a2rModels.Result.items)if(item.kind=="vegetation"){report.plants++;if(Mathf.Abs(item.webX-item.worldX*100)>.01f||Mathf.Abs(item.webY+item.worldZ*100)>.01f)report.failures.Add("XY drift "+item.id);var root=a2rModels.VisualRoot.Find(item.id+" vegetation "+item.model);if(root==null){report.failures.Add("Missing plant "+item.id);continue;}var lod=root.GetComponent<LODGroup>();if(lod==null||lod.GetLODs().Length!=3)report.lodFailures++;foreach(var r in root.GetComponentsInChildren<MeshRenderer>(true)){if(r.shadowCastingMode!=ShadowCastingMode.Off)report.shadowFailures++;foreach(var m in r.sharedMaterials)if(m!=null&&m.shader.name.Contains("/Lit")){if(!m.IsKeywordEnabled("_SPECULARHIGHLIGHTS_OFF")||!m.IsKeywordEnabled("_ENVIRONMENTREFLECTIONS_OFF"))report.keywordFailures++;if(!m.HasProperty("_A2R3DWind")||m.GetVector("_A2R3DWind").x<=0)report.failures.Add("Wind missing "+item.id);}}}
