    for(int look=0;look<2;look++){a2rModels.SetLook(look==1);for(int n=0;n<12;n++){UpdateViews();yield return null;}string id="r18-"+names[s]+"-1920-"+look;yield return A2RPlayShot(id);int visible=0,far=0;foreach(var e in Simulation.Enemies)if(e.Alive){var v=r3Cam.WorldToViewportPoint(NativeRemodel3D.Point(e.X,e.Y)+Vector3.up*.8f);if(v.z>0&&v.x>0&&v.x<1&&v.y>0&&v.y<1){visible++;if(Vector2.Distance(p,new Vector2(e.X,e.Y))>=800)far++;}}if(look==0){eye=r3Cam.transform.position;fov=r3Cam.fieldOfView;}bool same=Vector3.Distance(eye,r3Cam.transform.position)<.001f&&Mathf.Abs(fov-r3Cam.fieldOfView)<.001f;receipt.frames.Add(new NightFrame{id=id,look=look==0?"r14 shortcut 3D OFF same-package mode":"r18",core=p,eye=r3Cam.transform.position,pitch=r3Cam.transform.eulerAngles.x,fov=r3Cam.fieldOfView,width=Screen.width,height=Screen.height,visibleEnemies=visible,distantEnemies=far,cameraUnchanged=same});if(!same||Mathf.Abs(r3Cam.transform.eulerAngles.x-34)>.05f)report.failures.Add(id+": camera changed");if(s==3&&far<3)report.failures.Add(id+": distant enemies missing");}
   }
