   foreach(var cardId in new[]{"fern_cluster_0","fern_cluster_2","r4_low_brush_4"}){var item=a2rModels.Result.items.Find(x=>x.id==cardId);if(item==null){report.failures.Add("Crop plant missing "+cardId);continue;}yield return R18Pose(new Vector2(item.webX,item.webY+240));var v=r3Cam.WorldToScreenPoint(new Vector3(item.worldX,item.groundY+item.height*.5f,item.worldZ));var row=new R18Crop{id="r18-foliage-"+report.crops.Count,card=cardId,model=item.model,screen=new Vector2(v.x,Screen.height-v.y),core=new Vector2(Simulation.Player.X,Simulation.Player.Y)};for(int look=0;look<2;look++){a2rModels.SetLook(look==1);for(int n=0;n<12;n++){UpdateViews();yield return null;}yield return A2RPlayShot(row.id+"-"+look);}report.crops.Add(row);}
   sight=new SightReceipt();a2rModels.SetLook(true);yield return A2RSightFind(new Vector2(1300,3820),"m_ctree15");if(!sightFound)sight.failures.Add("No legal sight-1 point");else{yield return A2RSightWalk(sightPoint);foreach(bool on in new[]{false,true}){a2rOcclusion.SetMasksEnabled(on);yield return new WaitForSecondsRealtime(.36f);string id="r18-sight-1-1920-"+(on?"on":"off");yield return A2RPlayShot(id);sight.shots.Add(new SightShot{id=id,occluder="m_ctree15",core=new Vector2(Simulation.Player.X,Simulation.Player.Y),width=1920,on=on,heroSurfaces=a2rOcclusion.HeroSightSurfaces,partialHeroSurfaces=a2rOcclusion.HeroPartialSurfaces,gpuPixels=on?a2rOcclusion.NearestCoveredPixels():0,surfaces=new List<string>(a2rOcclusion.HitNames)});if(on&&(a2rOcclusion.HeroSightSurfaces==0||a2rOcclusion.NearestCoveredPixels()==0))sight.failures.Add("Sight-1 not exercised");}}
   a2rOcclusion.SetMasksEnabled(true);sight.passed=sight.failures.Count==0&&sight.shots.Count==2;a2rPlay.sightVerified=sight.passed;foreach(var f in sight.failures)report.failures.Add(f);File.WriteAllText(Path.Combine(a2rPlayOutput,"r18-sight1.json"),JsonUtility.ToJson(sight,true));Simulation.Config.EnemyAiEnabled=ai;
   if(report.plants!=113||report.forestWalls!=6||report.floor!=4||report.shadowFailures+report.keywordFailures+report.lodFailures>0)report.failures.Add("R18 foliage/card/render policy mismatch");foreach(var f in report.failures)a2rPlay.failures.Add(f);a2rPlay.visualFixture=report.scope;File.WriteAllText(Path.Combine(a2rPlayOutput,"r18-report.json"),JsonUtility.ToJson(report,true));
  }
 }
